import java.io.*;
import java.util.*;

public class Task7 {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        //Enter code here utkarsh
        //SHOW_TIME = true;
        int n =in.nextInt();
        int B = in.nextInt();


        int a[] = new int [n];
        for (int i = 0; i < n; i++){
            a[i] = in.nextInt();
        }

        int even = 0, odd = 0;
        ArrayList <Integer> dp = new ArrayList<>();
        for(int i = 0; i < n; i++) {
            if(a[i]%2 == 0) even++;
            else    odd++;
            if(even == odd && i < n-1) dp.add(Math.abs(a[i] - a[i+1]));
        }
        Collections.sort(dp);
        int ans = 0;
        for(int x : dp) {
            if(B < x)   break;
            ans++;
            B -= x;
        }
        System.out.println(ans);
    }
}
